// Subscribe once, for example in the form constructor
ofd.FileOk += Ofd_FileOk;

private void Ofd_FileOk(object sender, CancelEventArgs e)
{
    if (new System.IO.FileInfo(ofd.FileName).Length > 10000000)
    {
        e.Cancel = true;
        MessageBox.Show("Please choose a file smaller than 10 MB.");
    }
}

// Subscribe once, for example in the form constructor
sfd.FileOk += Sfd_FileOk;

private void Sfd_FileOk(object sender, CancelEventArgs e)
{
    if (sfd.FileName.Contains(" "))
    {
        e.Cancel = true;
        MessageBox.Show("Please use a file name without spaces.");
    }
}

